"""Segment list for the VANTA assembly film. Shared by the Blender build (bl_build.py) and the compositor (post.py).
Text follows VANTA_assembly_guide.pdf (guide6.py). Steps 14 and 15 are paraphrased from README.md (their v4 pages are not in the source)."""
FPS = 24
LEAD = 2          # the leg used for close-ups (MR, like the guide renders)
ISO = (0.75, 0.5, 0.42)
UNDER = (0.55, 0.6, -0.6)


def step(n, cat, title, blurb, grab, do, check, badge="", view=None, **k):
    d = dict(kind="step", id=f"s{n:02d}", n=n, cat=cat, tag=f"#STEP{n:02d} · {cat}", title=title, blurb=blurb, grab=grab, do=do, check=check,
             badge=badge, view=view or dict(dir=ISO, dist=900, target=(0, 0, 20), orbit=8), dur=7.8 + 2.4 * len(do))
    d.update(k); return d


