# fill defaults
_t = 0.0
for s in SEGMENTS:
    s.setdefault("layout", "place"); s.setdefault("layout_end", s["layout"]); s.setdefault("reset", False)
    s.setdefault("show", []); s.setdefault("hide", []); s.setdefault("new", []); s.setdefault("highlight", []); s.setdefault("targets", [])
    s.setdefault("per_leg", True); s.setdefault("stagger", 0.5); s.setdefault("spread", 0.0); s.setdefault("ghost", False)
    s.setdefault("shift", -0.13); s.setdefault("t_offset", 0.0); s.setdefault("explode_override", None)
    s["t0"] = _t; s["f0"] = int(round(_t * FPS)) + 1; _t += s["dur"]; s["f1"] = int(round(_t * FPS))
TOTAL_FRAMES = SEGMENTS[-1]["f1"]

if __name__ == "__main__":
    for s in SEGMENTS: print(f"{s['id']:8s} {s['f0']:5d}-{s['f1']:5d}  {s['dur']:5.1f}s")
    print("total", TOTAL_FRAMES, "frames =", round(TOTAL_FRAMES / FPS / 60, 2), "min")


